CREATE TABLE IF NOT EXISTS student_records (id VARCHAR(64) PRIMARY KEY,institution_id VARCHAR(64) NOT NULL,account_id VARCHAR(64) NOT NULL,matricule VARCHAR(80) NOT NULL,admission_review_id VARCHAR(64) NOT NULL UNIQUE,application_id VARCHAR(64) NOT NULL,program_unit_id VARCHAR(64) NOT NULL,curriculum_id VARCHAR(64) NOT NULL,cohort_id VARCHAR(64) NOT NULL,given_names VARCHAR(160) NOT NULL,family_name VARCHAR(120) NOT NULL,birth_date VARCHAR(20),nationality_code VARCHAR(8),email VARCHAR(320),phone_number VARCHAR(40),state VARCHAR(24) NOT NULL,row_version INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_student_record_account UNIQUE(institution_id,account_id),CONSTRAINT uq_student_record_matricule UNIQUE(institution_id,matricule));
CREATE INDEX IF NOT EXISTS ix_student_records_institution_state ON student_records(institution_id,state);
CREATE INDEX IF NOT EXISTS ix_student_records_program_cohort ON student_records(program_unit_id,cohort_id);
CREATE TABLE IF NOT EXISTS student_academic_registrations (id VARCHAR(64) PRIMARY KEY,student_id VARCHAR(64) NOT NULL,institution_id VARCHAR(64) NOT NULL,academic_year_id VARCHAR(64) NOT NULL,cohort_id VARCHAR(64) NOT NULL,curriculum_id VARCHAR(64) NOT NULL,state VARCHAR(24) NOT NULL,registered_by VARCHAR(64) NOT NULL,registered_at TIMESTAMPTZ NOT NULL,row_version INTEGER NOT NULL,CONSTRAINT uq_student_registration_year UNIQUE(student_id,academic_year_id));
CREATE INDEX IF NOT EXISTS ix_student_registrations_institution_year ON student_academic_registrations(institution_id,academic_year_id);
CREATE TABLE IF NOT EXISTS student_record_events (id VARCHAR(64) PRIMARY KEY,student_id VARCHAR(64) NOT NULL,actor_id VARCHAR(64) NOT NULL,event_type VARCHAR(80) NOT NULL,from_state VARCHAR(24),to_state VARCHAR(24),note VARCHAR(1000),created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS ix_student_record_events_student_created ON student_record_events(student_id,created_at);
CREATE TABLE IF NOT EXISTS student_matricule_sequences (institution_id VARCHAR(64) NOT NULL,academic_year_id VARCHAR(64) NOT NULL,next_value INTEGER NOT NULL,PRIMARY KEY(institution_id,academic_year_id));
CREATE TABLE IF NOT EXISTS student_course_registrations (id VARCHAR(64) PRIMARY KEY,registration_id VARCHAR(64) NOT NULL,student_id VARCHAR(64) NOT NULL,curriculum_course_id VARCHAR(64) NOT NULL,semester INTEGER NOT NULL,course_code VARCHAR(80),course_title VARCHAR(300) NOT NULL,credits VARCHAR(32),state VARCHAR(24) NOT NULL,created_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_student_course_registration UNIQUE(registration_id,curriculum_course_id));
CREATE INDEX IF NOT EXISTS ix_student_course_registrations_student_semester ON student_course_registrations(student_id,semester);
